import math
import sys
from functools import cmp_to_key

def solution(input_data):
    # Parse input
    lines = input_data.strip().split('\n')

    first_line = lines[0].split()
    k, n, m = int(first_line[0]), int(first_line[1]), int(first_line[2])

    second_line = lines[1].split()
    skills = [int(x) for x in second_line]

    improvements = []
    for i in range(n):
        parts = lines[2 + i].split()
        t = int(parts[0])
        idx = int(parts[1]) - 1  # 1-indexed to 0-indexed
        b = int(parts[2])
        improvements.append({
            'type': t,
            'skill_idx': idx,
            'val': b,
            'id': i + 1
        })

    # Greedy approach: calculate the benefit of each improvement
    # and pick the top m improvements

    benefit = []
    for imp in improvements:
        t = imp['type']
        skill_idx = imp['skill_idx']
        b = imp['val']
        skill_val = skills[skill_idx]

        if t == 1:  # Assign
            new_val = b
            # Calculate log ratio
            if skill_val > 0 and new_val > 0:
                log_gain = math.log(new_val) - math.log(skill_val)
            else:
                log_gain = float('-inf')
        elif t == 2:  # Add
            new_val = skill_val + b
            if skill_val > 0 and new_val > 0:
                log_gain = math.log(new_val) - math.log(skill_val)
            else:
                log_gain = float('-inf')
        elif t == 3:  # Multiply
            new_val = skill_val * b
            if skill_val > 0 and new_val > 0:
                log_gain = math.log(new_val) - math.log(skill_val)
            else:
                log_gain = float('-inf')
        else:
            continue

        benefit.append((log_gain, imp))

    # Sort by benefit in descending order
    benefit.sort(key=cmp_to_key(lambda x, y: y[0] - x[0]))

    # Pick top m improvements
    top_improvements = [b[1] for b in benefit[:m]]

    # Output
    result = []
    if top_improvements:
        result.append(str(len(top_improvements)))
        result.append(' '.join(str(imp['id']) for imp in top_improvements))
    else:
        result.append('0')
        result.append('')

    return '\n'.join(result)
