def solve_linear_system(A, B):
    """Solve 3x3 linear system Ax = B using Gaussian elimination"""
    n = len(A)
    aug = [A[i][:] + [B[i]] for i in range(n)]

    for i in range(n):
        max_row = i
        for k in range(i + 1, n):
            if abs(aug[k][i]) > abs(aug[max_row][i]):
                max_row = k
        aug[i], aug[max_row] = aug[max_row], aug[i]

        if abs(aug[i][i]) < 1e-12:
            return None

        for k in range(i):
            if abs(aug[i][i]) != 0:
                factor = aug[k][i] / aug[i][i]
                for j in range(i, n + 1):
                    aug[k][j] -= factor * aug[i][j]

        for k in range(n):
            if abs(aug[k][k]) < 1e-12:
                continue
            for j in range(k + 1, n + 1):
                aug[k][j] /= aug[k][k]

    result = [aug[i][n] for i in range(n)]
    return result

def compute_circumsphere(p1, p2, p3, p4):
    A = [
        [2.0 * (p2[k] - p1[k]) for k in range(3)],
        [2.0 * (p3[k] - p1[k]) for k in range(3)],
        [2.0 * (p4[k] - p1[k]) for k in range(3)]
