Let me trace through the logic:
- Block 1: "1" (length 1)
- Block 2: "12" (length 2)
- Block 3: "123" (length 3)
- Block i: "123...i" with length = sum of digit counts of numbers 1 to i

The key insight is that the total length up to block n is the sum of all block lengths from 1 to n.

```python
# filename: solution.py
import os

def solution(data):
    lines = data.strip().split('\n')
    if not lines:
        return ""
    q = int(lines[0])

    def count_total_digits(n):
        """Returns total number of digits in numbers 1 to n"""
        return sum(len(str(j)) for j in range(1, n + 1))

    def find_digit_at(k):
        """Find the digit at position k (1-indexed) in the sequence"""
        i = 1
        cumulative_before = 0

        # Find which block contains position k
        while True:
            block_length = count_total_digits(i)
            cumulative_with_i = cumulative_before + block_length
            if cumulative_with_i >= k:
                break
            cumulative_before = cumulative_with_i
            i += 1

        # Find offset within block i
        offset = k - 1 - cumulative_before  # 0-indexed

        # Find which number in block i contains this offset
        number = 1
        while number <= i:
            s = str(number)
            if offset < len(s):
                return s[offset]
            offset -= len(s)
            number += 1

    queries = []
    for i in range(1, q + 1):
        queries.append(int(lines[i]))

    results = []
    for k in queries:
        results.append(str(find_digit_at(k)))

    return '\n'.join(results)


