def solution(input_str):
    MAX_N = 1000001
    MOD = 10**9 + 7

    # Precompute smallest prime factor using sieve
    spf = list(range(MAX_N))
    for i in range(2, int(MAX_N**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, MAX_N, i):
                if spf[j] == j:
                    spf[j] = i

    # Precompute factorials and inverse factorials for binomial coefficients
    fact = [1] * MAX_N
    inv = [1] * MAX_N

    for i in range(1, MAX_N):
        fact[i] = (fact[i-1] * i) % MOD

    inv[MAX_N-1] = pow(fact[MAX_N-1], MOD - 2, MOD)
    for i in range(MAX_N - 2, -1, -1):
        inv[i] = (inv[i+1] * (i+1)) % MOD

    def nCr_mod(n, r):
        if r < 0 or r > n:
            return 0
        num = fact[n]
        den = (inv[r] * inv[n - r]) % MOD
        return (num * den) % MOD

    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    q = int(lines[0])
    results = []

    for i in range(1, q + 1):
        r_str, n_str = lines[i].split()
        r = int(r_str)
        n = int(n_str)

        if r == 0:
            # f0(n) = 2^(number of distinct prime factors)
            cnt = 0
            temp = n
            while temp > 1:
                p = spf[temp]
                cnt += 1
                while temp % p == 0:
                    temp //= p
            result = pow(2, cnt, MOD)
        else:
            # fr(n) for r > 0 using the formula
            temp = n
            result = 1
            while temp > 1:
                p = spf[temp]
                a = 0
                while temp % p == 0:
                    a += 1
                    temp //= p

                # fr(p^a) = C(a+r-1, r-1) + 2*C(a+r-1, r)
                term1 = nCr_mod(a + r - 1, r - 1)
                term2 = (2 * nCr_mod(a + r - 1, r)) % MOD
                term = (term1 + term2) % MOD
                result = (result * term) % MOD

        results.append(str(result))

    return '\n'.join(results)
