        parts = lines[i].split()
        x, y, d, tstart, elem = map(int, parts)
        transformers.append((x, y, d, tstart, elem))

    # Precompute cell events using sparse mapping
    # Each transformer has a 4-cycle pattern of positions
    cell_ts = defaultdict(list)

    for tx, ty, td, tstart, elem in transformers:
        # 4 positions in cycle
        for idx, (pr, pc) in enumerate([
            (tx, ty),
            (tx + td, ty - td),
            (tx + td, ty),
            (tx, ty + td)
        ]):
            if 0 <= pr < n and 0 <= pc < m:
                # Appears at tstart+idx, tstart+idx+4, tstart+idx+8, ...
                for ts in range(tstart + idx, n + m - 1, 4):
                    cell_ts[(pr, pc)].append((ts, elem))

    # Compute cumulative cost at each cell when visited
    cell_cost = {}
    for (r, c), events in cell_ts.items():
        events.sort()
        cum = 0
        for ts, cost in events:
            cum += cost
        cell_cost[(r, c)] = cum

    # DP: dp[r][c] = minimum cost to reach cell (r,c)
    dp = [[0] * m for _ in range(n)]

    for r in range(n):
        for c in range(m):
            if r == 0 and c == 0:
                continue

            cost_here = cell_cost.get((r, c), 0)

            if r > 0:
                dp[r][c] = min(dp[r][c], dp[r-1][c]) + cost_here
            if c > 0:
                dp[r][c] = min(dp[r][c], dp[r][c-1]) + cost_here

    return str(dp[n-1][m-1]) + '\n'
