def main():
    data = sys.stdin.read().split()
    idx = 0

    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1

    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        w = int(data[idx]); idx += 1
        adj[u].append((v, w))

    q = int(data[idx]); idx += 1
    queries = []
    for _ in range(q):
        v = int(data[idx]); idx += 1
        s = int(data[idx]); idx += 1
        t = int(data[idx]); idx += 1
        queries.append((v, s, t))

    # Tarjan's SCC
    ids = [-1] * (n + 1)
    scc_id = [0] * (n + 1)
    scc_cnt = 0
    stack = []
    on_stack = [False] * (n + 1)
    timer = 0

    def tarjan(u):
        nonlocal timer, scc_cnt
        ids[u] = low[u] = timer
        stack.append(u)
        on_stack[u] = True
        timer += 1

        for v, w in adj[u]:
            if ids[v] == -1:
                tarjan(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], ids[v])

        if low[u] == ids[u]:
            while stack:
                x = stack.pop()
                on_stack[x] = False
                scc_id[x] = scc_cnt
                if x == u:
                    break
            scc_cnt += 1

    for i in range(1, n + 1):
        if ids[i] == -1:
            tarjan(i)

    scc_nodes = [[] for _ in range(scc_cnt)]
    for i in range(1, n + 1):
        scc_nodes[scc_id[i]].append(i)

    scc_gcd = [0] * scc_cnt

    for scc in range(scc_cnt):
        comp = scc_nodes[scc]
        if len(comp) <= 1:
            continue

        # DFS to find fundamental cycles
        node_idx = {u: 0 for u in comp}
        tree_weights = {u: 0 for u in comp}

        root = comp[0]
        stack_list = [root]
        visited_tree = set([root])

        while stack_list:
            u = stack_list[-1]

            if node_idx[u][0] < len(adj[u]):
                v, w = adj[u][node_idx[u][0]]
                node_idx[u] = (0, v + w, scc_cnt)
                node_idx[u] = (v + w, scc_id[v], u)

                if scc_id[v] == scc:
                    if v in visited_tree:
                        g_inc = math.gcd(scc_gcd[scc], w)
                        scc_gcd[scc] = g_inc
                    else:
                        visited_tree.add(v)
                        tree_weights[v] = tree_weights[u] + w
                        stack_list.append(v)
                else:
                    continue
            else:
                stack_list.pop()

        # Use simpler cycle detection
        visited = {root}
        weights = {root: 0}
        parent = {}
        q_stack = [root]

        while q_stack:
            u = q_stack[-1]
            q_stack.pop()

            for v, w in adj[u]:
                if scc_id[v] != scc:
                    continue
                if v in visited:
                    cycle_len = (weights[u] + w) - weights[v]
                    g_val = math.gcd(scc_gcd[scc], abs(cycle_len))
                    scc_gcd[scc] = g_val
                else:
                    visited.add(v)
                    weights[v] = weights[u] + w
                    parent[v] = u
                    q_stack.append(v)

        if scc_gcd[scc] == 0:
            scc_gcd[scc] = 1

    results = []
    for v, s, t in queries:
        gcd_vals = scc_gcd[scc_id[v]]

        if gcd_vals == 0:
            if s % t == 0:
                results.append('YES')
            else:
                results.append('NO')
        else:
            g = math.gcd(gcd_vals, t)
            if s % g == 0:
                results.append('YES')
            else:
                results.append('NO')

    print('\n'.join(results))

if __name__ == "__main__":
    main()
