import random
import sys

def check(n, adj, a, x):
    """Check if assignment x is valid."""
    for i in range(1, n + 1):
        v_i = x[i]
        for neighbor in adj[i]:
            v_i += x[neighbor]
        if v_i == a[i - 1]:
            return False
    return True

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    a = list(map(int, lines[m + 1].split()))

    def try_random_search(max_trials=20000):
        for _ in range(max_trials):
            x = [0] + [random.choice([0, 1]) for _ in range(n)]
            if check(n, adj, a, x):
                s = [i for i in range(1, n + 1) if x[i]]
                return s
        return None

    def try_deterministic_patterns():
        patterns = [
            lambda i, a: a[i-1] == 0,
            lambda i, a: a[i-1] != 0,
            lambda i, a: a[i-1] % 2 == 0,
            lambda i, a: a[i-1] % 2 == 1,
            lambda i, a: a[i-1] > 0,
            lambda i, a: a[i-1] <= 0,
        ]

        for pat in patterns:
            x = [0] * (n + 1)
            for i in range(1, n + 1):
                x[i] = 1 if pat(i, a) else 0
            if check(n, adj, a, x):
                s = [i for i in range(1, n + 1) if x[i]]
                return s
        return None

    random.seed(42)
    result = try_deterministic_patterns()

    if result is None:
        result = try_random_search()

    if result is None:
        result = list(range(1, n + 1))

    if result:
        return f"{len(result)}\n{' '.join(map(str, result))}"
    else:
        return "-1"
